INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (1, N'What is object-oriented programming?', N'Object-oriented programming organises code using classes and objects. and others', N'Beginner', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (2, N'What is the difference between an interface and an abstract class?', N'An interface defines a contract, while an abstract class can provide shared implementation and state. lets see', N'Intermediate', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (3, N'How do you prioritise multiple urgent tasks?', N'I assess deadlines, importance and dependencies, then communicate priorities and track progress.', N'Beginner', 1, 2)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (4, N'How do you handle confidential documents?', N'I follow access controls, organisational policies and secure storage procedures.', N'Intermediate', 1, 2)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (5, N'How do you motivate an underperforming team?', N'I identify barriers, agree on achievable goals, provide support and monitor improvement.', N'Intermediate', 1, 4)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (6, N'How would you resolve conflict between two employees?', N'I listen impartially, establish the facts, facilitate discussion and agree on appropriate actions.', N'Intermediate', 1, 4)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (7, N'What is the difference between assets and liabilities?', N'Assets are resources controlled by an organisation, while liabilities are its obligations.', N'Beginner', 1, 6)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (8, N'What is bank reconciliation?', N'It is the process of comparing bank records with accounting records and resolving differences.', N'Intermediate', 1, 6)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (9, N'What is dependency injection in ASP.NET Core?', N'Dependency injection is a design pattern that supplies dependencies to a class rather than creating them internally. ASP.NET Core provides a built-in dependency injection container that improves testability, maintainability and loose coupling.', N'Advanced', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (10, N'What is middleware in ASP.NET Core, and why is it important?', N'Middleware components process HTTP requests and responses in the ASP.NET Core request pipeline. They can handle authentication, routing, error handling and other application concerns.', N'Intermediate', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (11, N'What is the purpose of exception handling in C#?', N'Exception handling allows developers to manage runtime errors using try, catch and finally blocks, helping prevent unexpected application termination.', N'Beginner', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (12, N'How would you handle an unhappy customer?', N'I would listen carefully, acknowledge the customer''s concerns, remain professional, and work towards a suitable resolution.', N'Intermediate', 1, 8)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (13, N'What software Development', N'Software development is building software from start to finish, and you manage both the back end and the front end.', N'Beginner', 1, 1)
INSERT [dbo].[InterviewQuestions] ([Id], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [IsActive], [InterviewCategoryId]) VALUES (14, N'What is administration', N'Doing what your boss, who earns two times your salary, cannot do, like saving a PDF', N'Beginner', 1, 2)
