INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (1, 53, 5, N'How do you motivate an underperforming team?', N'I identify barriers, agree on achievable goals, provide support and monitor improvement.', N'Intermediate', 1, CAST(N'2026-11-13T09:54:16.4123368' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (2, 53, 6, N'How would you resolve conflict between two employees?', N'I listen impartially, establish the facts, facilitate discussion and agree on appropriate actions.', N'Intermediate', 2, CAST(N'2026-11-13T09:54:16.4123368' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (3, 54, 3, N'How do you prioritise multiple urgent tasks?', N'I assess deadlines, importance and dependencies, then communicate priorities and track progress.', N'Beginner', 1, CAST(N'2026-11-13T10:47:31.4007750' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (4, 54, 4, N'How do you handle confidential documents?', N'I follow access controls, organisational policies and secure storage procedures.', N'Intermediate', 2, CAST(N'2026-11-13T10:47:31.4007750' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (5, 55, 1, N'What is object-oriented programming?', N'Object-oriented programming organises code using classes and objects.', N'Beginner', 1, CAST(N'2026-11-14T08:56:06.8696367' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (6, 55, 2, N'What is the difference between an interface and an abstract class?', N'An interface defines a contract, while an abstract class can provide shared implementation and state.', N'Intermediate', 2, CAST(N'2026-11-14T08:56:06.8696367' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (7, 55, 9, N'What is dependency injection in ASP.NET Core?', N'Dependency injection is a design pattern that supplies dependencies to a class rather than creating them internally. ASP.NET Core provides a built-in dependency injection container that improves testability, maintainability and loose coupling.', N'Advanced', 3, CAST(N'2026-11-14T08:56:06.8696367' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (8, 55, 10, N'What is middleware in ASP.NET Core, and why is it important?', N'Middleware components process HTTP requests and responses in the ASP.NET Core request pipeline. They can handle authentication, routing, error handling and other application concerns.', N'Intermediate', 4, CAST(N'2026-11-14T08:56:06.8696367' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (9, 56, 1, N'What is object-oriented programming?', N'Object-oriented programming organises code using classes and objects.', N'Beginner', 1, CAST(N'2026-11-14T09:12:58.0508518' AS DateTime2))
INSERT [dbo].[InterviewSessionQuestions] ([Id], [InterviewSessionId], [InterviewQuestionId], [QuestionText], [SuggestedAnswer], [DifficultyLevel], [DisplayOrder], [AssignedAtUtc]) VALUES (10, 56, 2, N'What is the difference between an interface and an abstract class?', N'An interface defines a contract, while an abstract class can provide shared implementation and state.', N'Intermediate', 2, CAST(N'2026-11-14T09:12:58.0508518' AS DateTime2))
