INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (59, 56, 1, N'A programming approach that uses classes and objects to organise software.', CAST(N'2026-11-14T09:13:32.9202527' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (60, 57, 1, N'Object-oriented programming means classes are database tables, objects are SQL queries, encapsulation means deleting files, and reusable code means copying passwords.', CAST(N'2026-11-14T09:19:43.3684305' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (61, 58, 1, N'My favourite holiday destination is Cape Town. I enjoy visiting the beach, exploring restaurants, and spending time with family. The weather is beautiful during summer.', CAST(N'2026-11-14T09:39:10.6230858' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (62, 59, 1, N'Object-oriented programming means classes are database tables, objects are SQL queries, encapsulation means deleting files, and reusable code means copying passwords.', CAST(N'2026-11-14T10:09:54.2313353' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (63, 60, 1, N'Object-oriented programming organises software using classes and objects. Classes define structures and behaviours, while objects are instances of classes. Encapsulation protects an object''s internal state by controlling access to its data. Reusable code allows developers to use existing functionality instead of unnecessarily duplicating implementations.', CAST(N'2026-11-14T10:11:23.9554147' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (64, 61, 1, N'Object-oriented programming uses classes and objects. Classes are not database tables, and objects are not SQL queries. Encapsulation does not mean deleting files; it protects an object''s internal state. Reusable code does not mean copying passwords; it means using existing functionality.', CAST(N'2026-11-14T10:12:34.9787242' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (65, 62, 1, N'Object-oriented programming uses classes and objects. It is false that classes are database tables. Objects are instances of classes. Encapsulation protects internal data, and reusable code allows developers to reuse existing functionality.', CAST(N'2026-11-14T10:13:59.6274546' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (66, 63, 1, N'Object-oriented programming uses classes and objects. It is false that classes are database tables. Objects are instances of classes. Encapsulation protects internal data, and reusable code allows developers to reuse existing functionality.', CAST(N'2026-11-14T10:18:53.8000648' AS DateTime2))
INSERT [dbo].[InterviewResponses] ([Id], [InterviewSessionId], [InterviewQuestionId], [AnswerText], [SubmittedAt]) VALUES (67, 64, 1, N'Object-oriented programming means classes are database tables, objects are SQL queries, encapsulation means deleting files, and reusable code means copying passwords.', CAST(N'2026-11-14T10:20:14.6781117' AS DateTime2))
