INSERT [dbo].[InterviewQuestionRubrics] ([Id], [InterviewQuestionId], [ExpectedConcepts], [AcceptableAlternatives], [AssessmentGuidance], [TechnicalAccuracyMarks], [KeyConceptMarks], [ClarityMarks], [PracticalExampleMarks], [IsActive], [CandidateGuidance]) VALUES (1, 1, N'Classes; objects; encapsulation; reusable code', N'reusable code = code reuse', N'Assess whether the answer explains organising software using classes and objects. Award additional credit for accurately explaining relevant principles and providing a practical example.', 4, 3, 2, 1, 1, N'Strengthen your explanation of object-oriented programming by describing how classes and objects work together. Explain encapsulation and code reuse in your own words, and include a practical programming example.')
INSERT [dbo].[InterviewQuestionRubrics] ([Id], [InterviewQuestionId], [ExpectedConcepts], [AcceptableAlternatives], [AssessmentGuidance], [TechnicalAccuracyMarks], [KeyConceptMarks], [ClarityMarks], [PracticalExampleMarks], [IsActive], [CandidateGuidance]) VALUES (2, 2, N'Interface defines a contract; abstract class can provide shared implementation and state', N'Interface defines a contract = Interface specifies behaviour
abstract class can provide shared implementation and state = abstract class supports common code', N'Assess accurate distinctions between interfaces and abstract classes. Give credit for relevant language-specific examples.', 4, 3, 2, 1, 1, N'Explain how an interface defines a contract and how an abstract class can provide shared implementation. Compare their purposes, describe when you would choose each one, and include a practical C# example.')
INSERT [dbo].[InterviewQuestionRubrics] ([Id], [InterviewQuestionId], [ExpectedConcepts], [AcceptableAlternatives], [AssessmentGuidance], [TechnicalAccuracyMarks], [KeyConceptMarks], [ClarityMarks], [PracticalExampleMarks], [IsActive], [CandidateGuidance]) VALUES (3, 3, N'Assess deadlines; evaluate importance; identify dependencies; communicate priorities; track progress', N'evaluate importance = impact
communicate priorities = stakeholder communication', N'Assess a practical prioritisation process that considers urgency, importance and dependencies.', 4, 3, 2, 1, 1, N'Describe how you assess urgency, deadlines, importance and the consequences of delays. Explain how you organise competing priorities, communicate changes and ensure critical tasks are completed. Include a real workplace example.')
